import java.util.Scanner;
class Vehicle {
    private final String vehicleType;
    Vehicle(String vehicleType) { this.vehicleType = vehicleType; }
    void display() { System.out.println("Vehicle Type: " + vehicleType); }
}
public class Main {
    public static void main(String[] args) {
        String type = new Scanner(System.in).nextLine();
        new Vehicle(type).display();
    }
}
```
This full program assigns the input to the instance field and prints the entered vehicle type.
